preConditionHook:
// EXIT ON RETURN THROUGH THE BREAKOUT POINT (Brian's notes ON-31, #31), the
// exit for a fade of a breakout. The breakout point is the prior zoneBars-bar
// extreme as it stood before the SIGNAL bar: EL's Highest(...)[2] on
// the bar the entry fills, where the signal bar is [1]. BarsSinceEntry() is 0
// on the fill bar (and while flat; VERIFIED), so the level is captured on
// that bar and held for the life of the position -- StopAtSignalBarRangeMultiple's
// arrangement, which keeps the deepest subscript fixed at zoneBars + 1 instead
// of growing with the trade. A short exits on the first bar whose low trades
// back below the zone high; a long on the first bar whose high trades back
// above the zone low. Fills at the next open.
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    bpHigh = high[2];
    bpLow = low[2];
    for (int i = 1; i < (int)zoneBars; ++i) {
        if (el_gt(high[2 + i], bpHigh)) bpHigh = high[2 + i];
        if (el_lt(low[2 + i], bpLow)) bpLow = low[2 + i];
    }
}
